update public.site_settings set value=value||'{"accent": "#0B5FD6", "background": "#FBFBFD", "surface": "#FFFFFF", "textColor": "#1D1D1F", "secondary": "#FF7A45", "secondaryText": "#28180E", "soft": "#F0F3FA", "muted": "#64646F", "accentText": "#FFFFFF", "darkBackground": "#0B0B0F", "darkSurface": "#151519", "darkText": "#F5F5F7", "darkAccent": "#4C9AFF", "darkAccentText": "#0B0B0F", "darkSecondary": "#FF925F", "darkSecondaryText": "#28180E", "darkSoft": "#202027", "darkMuted": "#A9A9B5", "heroOverlay": "#10162B", "heroText": "#FFFFFF", "successColor": "#0B5FD6", "darkSuccessColor": "#89B8FF", "errorColor": "#AA3441", "darkErrorColor": "#FFABB5", "headingFont": "georgia", "bodyFont": "system", "radius": 24, "tagline": "Slow moments. Remarkable places. Journeys made around you."}'::jsonb||jsonb_build_object('ui',coalesce(value->'ui','{}'::jsonb)||'{"enquire": "Enquire", "discover": "Discover", "reviewCarousel": "Guest stories — swipe or use the arrow keys to explore", "theme": "Appearance", "light": "Light", "dark": "Dark"}'::jsonb) where slug='site-config';
update public.site_settings set value=jsonb_set(value,'{colors}','{"accent": "#0B5FD6", "background": "#FBFBFD", "surface": "#FFFFFF", "text": "#1D1D1F", "border": "#E4E4E9", "muted_text": "#64646F", "accent_text": "#FFFFFF", "secondary": "#FF7A45"}'::jsonb) where slug='theme';
