update public.page_sections set published=false where slug in ('home-why-us','home-slow-note','home-island-gallery','home-last-invitation');
insert into public.page_sections(slug,page_id,type,content,published,is_placeholder,sort_order) values ('home-journey-search',(select id from public.pages where slug='home'),'search_bar','{"heading": "Find a little more you."}'::jsonb,true,true,1) on conflict(slug) do update set content=excluded.content,type=excluded.type,sort_order=excluded.sort_order,published=true;
insert into public.page_sections(slug,page_id,type,content,published,is_placeholder,sort_order) values ('home-island-stats',(select id from public.pages where slug='home'),'stats','{"heading": "A small island. So much to discover.", "items": [{"title": "6", "body": "Sample journeys"}, {"title": "17", "body": "Places to discover"}, {"title": "Your pace", "body": "Every step of the way"}]}'::jsonb,true,true,3) on conflict(slug) do update set content=excluded.content,type=excluded.type,sort_order=excluded.sort_order,published=true;
insert into public.page_sections(slug,page_id,type,content,published,is_placeholder,sort_order) values ('home-how-it-works',(select id from public.pages where slug='home'),'how_it_works','{"heading": "A great journey starts\nwith a little conversation.", "body": "Beautifully simple, from your first idea to a journey that feels like you.", "items": [{"title": "Tell us what moves you", "body": "A window seat in the hills. A quiet beach. A little of everything. Share your dates, interests and preferred pace."}, {"title": "Make the journey yours", "body": "Explore a personal proposal with clear details and room to refine the places, stays and experiences that matter to you."}, {"title": "Leave space for wonder", "body": "Once arrangements are confirmed directly with the operator, look forward to the little moments between the landmarks."}]}'::jsonb,true,true,4) on conflict(slug) do update set content=excluded.content,type=excluded.type,sort_order=excluded.sort_order,published=true;
insert into public.page_sections(slug,page_id,type,content,published,is_placeholder,sort_order) values ('home-destination-edit',(select id from public.pages where slug='home'),'destinations','{"heading": "Different worlds.\nOne remarkable island.", "body": "Follow the mist, the ocean, or your curiosity. There is a place for every kind of traveller.", "limit": 5, "place_ids": [], "cta_label": "All destinations", "cta_href": "/destinations"}'::jsonb,true,true,5) on conflict(slug) do update set content=excluded.content,type=excluded.type,sort_order=excluded.sort_order,published=true;
update public.page_sections set content=content||jsonb_build_object('place_ids',(select jsonb_agg(id order by array_position(array['sigiriya','ella','galle','mirissa','yala'],slug)) from public.places where slug=any(array['sigiriya','ella','galle','mirissa','yala']))) where slug='home-destination-edit';
update public.page_sections set content=content||'{"heading": "Wonder,\nwithout the rush.", "eyebrow": "SRI LANKA · BEAUTIFULLY PERSONAL", "body": "Ancient stories. Mountain mornings. A little salt in the air.\nAn island journey, at your own pace.", "cta_label": "Find your journey", "cta_href": "/tours", "secondary_label": "Explore the island", "secondary_href": "/map", "scroll_label": "Let curiosity lead"}'::jsonb where slug='home-intro';
update public.page_sections set content=content||'{"heading": "Good journeys.\nEven better memories.", "body": "A considered collection of sample routes. Each one, a different way to fall for Sri Lanka.", "limit": 6, "cta_label": "Explore all journeys", "cta_href": "/tours"}'::jsonb where slug='home-featured-journeys';
update public.page_sections set content=content||'{"heading": "The best part?\nThe people along the way.", "eyebrow": "A MORE PERSONAL WAY TO TRAVEL", "body": "A favourite local stop. A story you would never find in a guidebook. Someone who understands when to explore — and when to simply enjoy the view.\n\nOur demo team roles show how your own hosts can bring a journey to life. The scenic photo is illustrative, not a staff portrait."}'::jsonb where slug='home-guide-story';
update public.page_sections set content=content||'{"heading": "A little inspiration.\nA whole island to explore.", "body": "Trace a sample journey from ancient cities to tea-covered hills and the Indian Ocean. Pick a place. Follow a feeling.", "cta_label": "Find your way around", "cta_href": "/map"}'::jsonb where slug='home-island-map';
update public.page_sections set content=content||'{"heading": "The moments\nthat stay with you.", "body": "Fictional guest stories for this website preview. A glimpse of how real travel memories can be shared.", "limit": 8, "cta_label": "Read the guest stories", "cta_href": "/reviews"}'::jsonb where slug='home-review-stories';
update public.page_sections set content=content||'{"heading": "A little clarity.\nA lot to look forward to.", "body": "The practical details, thoughtfully answered. Draft guidance to confirm with the operator.", "limit": 4}'::jsonb where slug='home-questions';
update public.page_sections set content=content||'{"heading": "Your kind of Sri Lanka.\nLet’s find it.", "body": "Tell us what you love. We’ll start with a conversation and a little island inspiration.", "cta_label": "Plan your trip", "cta_href": "/contact"}'::jsonb where slug='home-inquiry-band';
update public.page_sections set content=content||jsonb_build_object('image',(select photo_media_id from public.team_members where photo_media_id is not null order by sort_order limit 1)) where slug='home-guide-story';
update public.site_settings set value=value||'{"heading": "The island is just\nthe beginning.", "description": "Thoughtful journeys through remarkable places. Discover Sri Lanka, and a pace that feels like you."}'::jsonb where slug='footer';
